    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.5,
      "sub": "military",
      "order": "Increase military spending slightly to 2.5 percent of GDP to maintain regional deterrence."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": 0.5,
      "sub": "",
