    }
  ],
  "cables": [
    {
      "to": "CHN",
      "private": true,
      "text": "We value our strategic economic partnership and look forward to expanding bilateral trade and technological cooperation."
    },
    {
      "to": "RUS",
      "private": true,
      "text": "We reaffirm our commitment to deepening strategic coordination within the Shanghai Cooperation Organisation and BRICS frameworks."
    }
  ],
  "public_statement": "The Iranian government remains steadfast in its commitment to economic resilience, national sovereignty, and the welfare of all our citizens. We will continue to pursue independent development and constructive relations with our partners across Eurasia.",
