    {
      "when": "inflation_above:30",
      "do": {
        "type": "monetary_policy",
        "target": null,
        "amount": 0.25,
        "sub": "",
        "order": "Raise interest rates further if inflation exceeds thirty percent."
      }
    }
  ],
  "detailed_report": "economy"
}
